def getMonthlySales(month):
    # Bu fonksiyonun gerçek uygulaması verilmemiş, örnek bir değer döndürülür
    return month * 1000  # Örnek satış miktarı

def getQuarterlySales():
    total = 0
    for i in range(0, 3):
        total += getMonthlySales(i)
    return total
